#include "optimizer_induction.h"

#include "optimizer_helpers.h"
#include "optimizer_loop_internal.h"

/**
 * @brief Test whether an operand is the specified integer literal.
 *
 * @param operand Operand to inspect.
 * @param x Integer literal to match.
 * @return True if the literal matches.
 */
static bool constant_is(IrOperand operand, IrInt x) {
  return operand.type == IR_OP_INT32 && operand.value.int32_value == x;
}

/**
 * @brief Find the defining instruction that matches the requested operation.
 *
 * @param fn IR function under analysis.
 * @param operand Operand to inspect.
 * @return Defining load, or NULL.
 */
static const IrInstruction* load_of(IrFunction* fn, IrOperand operand) {
  if (operand.type != IR_OP_VALUE)
    return NULL;

  const IrInstruction* inst = optimizer_find_definition(fn, operand.value.id);
  return inst && inst->type == IR_INST_LOAD ? inst : NULL;
}

/**
 * @brief Check that the parameter slot is never overwritten by the function.
 *
 * @param fn IR function under analysis.
 * @param slot Stack slot to inspect.
 * @return True if the slot is never stored to.
 */
static bool immutable_slot(const IrFunction* fn, IrStackSlotId slot) {
  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    const IrInstructionArray* list = &fn->blocks.data[b].instructions;

    for (size_t i = 0; i < list->count; i++)
      if (list->data[i].type == IR_INST_STORE &&
          list->data[i].operands.store.target == slot)
        return false;
  }

  return true;
}

/**
 * @brief Check whether the instruction belongs to the supplied block.
 *
 * @param block Block or instruction list under analysis.
 * @param inst Instruction to locate.
 * @return True if the instruction belongs to the block.
 */
static bool in_block(const IrBlock* block, const IrInstruction* inst) {
  for (size_t i = 0; i < block->instructions.count; i++)
    if (&block->instructions.data[i] == inst)
      return true;

  return false;
}

/**
 * @brief Check whether values defined by the skipped header or remainder step
 * are used elsewhere.
 *
 * @param fn IR function under analysis.
 * @param head Candidate loop header.
 * @param step Remainder block proposed for bypass.
 * @return True if code outside the bypassed blocks uses one of their
 * definitions.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement"
// Changes: Reject skipping instructions if any of their outputs escape the
// skipped blocks.
static bool escapes(IrFunction* fn, IrBlock* head, IrBlock* step) {
  IrBlock* sources[] = {head, step};
  for (size_t k = 0; k < 2; k++) {
    IrInstructionArray* list = &sources[k]->instructions;
    for (size_t i = 0; i < list->count; i++) {
      IrValueId id = list->data[i].result;

      if (id == IR_INVALID_ID)
        continue;

      for (IrBlockId b = 0; b < fn->blocks.count; b++) {
        IrBlock* block = &fn->blocks.data[b];

        if (block == head || block == step)
          continue;

        for (size_t j = 0; j < block->instructions.count; j++)
          if (optimizer_loop_instruction_uses(&block->instructions.data[j], id))
            return true;

        IrOperand* operand =
            optimizer_loop_terminator_operand(&block->terminator);

        if (operand && optimizer_loop_direct_use(*operand, id))
          return true;
      }
    }
  }

  return false;
}

void optimizer_skip_zero_quotient_step(IrFunction* fn,
                                       const InductionLoop* range) {
  if (range->step != 1 || range->start < 0)
    return;

  const IrInstruction* limit = load_of(fn, range->bound);
  if (!limit || !immutable_slot(fn, limit->operands.load.source))
    return;

  // Match the slot initialization at entry to the inner Euclidean loop.
  IrBlock* entry = &fn->blocks.data[range->body];
  if (optimizer_loop_edge_count(fn, range->body) != 1 ||
      entry->terminator.type != IR_TERMINATOR_JUMP ||
      entry->instructions.count < 2)
    return;

  const IrInstruction* move_a =
      &entry->instructions.data[entry->instructions.count - 2];
  const IrInstruction* move_b = move_a + 1;
  if (move_a->type != IR_INST_STORE || move_b->type != IR_INST_STORE)
    return;

  IrStackSlotId a = move_a->operands.store.target,
                b = move_b->operands.store.target;

  if (a == b || a == range->slot || b == range->slot)
    return;

  const IrInstruction* from_a = load_of(fn, move_a->operands.store.source);
  const IrInstruction* from_b = load_of(fn, move_b->operands.store.source);

  if (!from_a || from_a->operands.load.source != range->slot ||
      !in_block(entry, from_a) || !from_b ||
      from_b->operands.load.source != limit->operands.load.source)
    return;

  // Check the rotated loop layout before bypassing the first remainder
  // computation.
  IrBlock* head = &fn->blocks.data[entry->terminator.value.jump_target];
  if (head->instructions.count != 2 ||
      head->terminator.type != IR_TERMINATOR_CONDITIONAL)
    return;

  const IrInstruction* check = &head->instructions.data[0];
  const IrInstruction* eq = check + 1;
  if (check->type != IR_INST_LOAD || check->operands.load.source != b ||
      eq->type != IR_INST_EQ || !constant_is(eq->operands.binary.right, 0) ||
      !optimizer_loop_direct_use(eq->operands.binary.left, check->result) ||
      !optimizer_loop_direct_use(
          head->terminator.value.conditional_target.condition, eq->result))
    return;

  IrBlock* step =
      &fn->blocks.data[head->terminator.value.conditional_target.false_target];
  if (step->instructions.count != 6 ||
      step->terminator.type != IR_TERMINATOR_JUMP)
    return;

  const IrInstruction* read_a = &step->instructions.data[0];
  const IrInstruction* read_b = read_a + 1;
  const IrInstruction* div = read_b + 1;
  const IrInstruction* mul = div + 1;
  const IrInstruction* sub = mul + 1;
  const IrInstruction* store = sub + 1;
  if (read_a->type != IR_INST_LOAD || read_a->operands.load.source != a ||
      read_b->type != IR_INST_LOAD || read_b->operands.load.source != b ||
      div->type != IR_INST_IDIV ||
      !optimizer_loop_direct_use(div->operands.binary.left, read_a->result) ||
      !optimizer_loop_direct_use(div->operands.binary.right, read_b->result) ||
      mul->type != IR_INST_MUL ||
      !optimizer_loop_direct_use(mul->operands.binary.left, div->result) ||
      !optimizer_loop_direct_use(mul->operands.binary.right, read_b->result) ||
      sub->type != IR_INST_SUB ||
      !optimizer_loop_direct_use(sub->operands.binary.left, read_a->result) ||
      !optimizer_loop_direct_use(sub->operands.binary.right, mul->result) ||
      store->type != IR_INST_STORE || store->operands.store.target != a ||
      !optimizer_loop_direct_use(store->operands.store.source, sub->result))
    return;

  if (escapes(fn, head, step))
    return;

  // The range edge proves 0 <= A < B. The rotated step leaves both
  // physical slots intact, so enter directly in the alternate layout.
  entry->terminator.value.jump_target = step->terminator.value.jump_target;
}
